// M0 gate: expand U2's full plugin set into a real entry point, bundle it, and
// report the residual Node builtins.
//
// This differs from the design doc's section 2.7 spike, which only bundled the
// main exports of 7 kernel packages. Passing this bundle is necessary but NOT
// sufficient — see the note on stub modules below. The authoritative gate is
// booting the result in workerd (`wrangler dev --local`).
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs'
import * as esbuild from 'esbuild'

const deps = Object.keys(JSON.parse(readFileSync('./scripts/u2-deps.json', 'utf8')))
if (!existsSync('./units/session-do/build')) mkdirSync('./units/session-do/build', { recursive: true })

// Stands in for the compile-time expansion described in design doc 10.6: every
// plugin row in cordis.session.yml becomes a static import. This is the only
// generated artifact; the Worker entry itself is hand-written source.
const generated = [
  '// GENERATED by scripts/m0-bundle.mjs - do not edit.',
  '// Compile-time expansion of the U2 plugin set (design doc 10.6).',
  ...deps.map((d, i) => `import * as p${i} from ${JSON.stringify(d)}`),
  '',
  `export const modules = {\n${deps.map((d, i) => `  ${JSON.stringify(d)}: p${i},`).join('\n')}\n}`,
].join('\n')
writeFileSync('./units/session-do/build/plugins.generated.js', generated)

const NODE_RE = /from\s*"node:([a-z_/]+)"|require\("node:([a-z_/]+)"\)|import\("node:([a-z_/]+)"\)/g

// Bare builtin specifiers (no `node:` prefix) do not resolve on workerd. Record
// who imports them and stub them out. This both yields the complete reachable
// surface and is the mitigation a real build would apply.
const BARE = ['assert','async_hooks','buffer','child_process','cluster','constants','crypto',
  'dgram','dns','domain','events','fs','http','http2','https','inspector','module','net','os',
  'path','perf_hooks','process','punycode','querystring','readline','repl','stream',
  'string_decoder','timers','tls','tty','url','util','v8','vm','worker_threads','zlib']
const bareHits = new Map()   // builtin -> Set(importer)

const stubPlugin = {
  name: 'record-and-stub-bare-builtins',
  setup(build) {
    const filter = new RegExp(`^(${BARE.join('|')})(/.*)?$`)
    build.onResolve({ filter }, (args) => {
      const mod = args.path.split('/')[0]
      if (!bareHits.has(mod)) bareHits.set(mod, new Set())
      bareHits.get(mod).add(args.importer.replace(/^.*node_modules[/\\]/, '').replace(/\\/g, '/'))
      return { path: args.path, namespace: 'bare-builtin' }
    })
    build.onLoad({ filter: /.*/, namespace: 'bare-builtin' }, (args) => ({
      contents: `export default {};\nexport const __stubbed = ${JSON.stringify(args.path)};`,
      loader: 'js',
    }))
  },
}

// M0 finding #1: four upstream packages (dsh-llm, dsh-repeat-tool-reminder,
// dsh-time-context, dsh-tmux-context) run
//     const { version } = createRequire(import.meta.url)("../package.json")
// at MODULE SCOPE to read their own version. On workerd `import.meta.url` is
// undefined, so this throws during import. A bundle-only check cannot see it.
const requireShim = {
  name: 'shim-create-require',
  setup(build) {
    build.onResolve({ filter: /^node:module$/ }, () => ({ path: 'node:module', namespace: 'mod-shim' }))
    build.onLoad({ filter: /.*/, namespace: 'mod-shim' }, () => ({
      contents: `
        // Serves exactly one use: reading a package's own package.json for its
        // version. Every other use should fail loudly rather than silently
        // return something wrong.
        export function createRequire() {
          return function req(id) {
            if (typeof id === 'string' && id.endsWith('package.json')) return { version: '0.1.0-rc.6' }
            throw new Error('createRequire shim: unsupported require(' + id + ') in workerd')
          }
        }
        export default { createRequire }
      `,
      loader: 'js',
    }))
  },
}

// M0 finding #2: workerd forbids I/O, timers and random-number generation at
// MODULE SCOPE (Node has no such rule). dsh-anonymous-user-id generates/reads an
// anonymous id with randomUUID + fs at module scope, so importing it throws.
// It is a dependency of dsh-llm-deepseek (a core M1 provider), so "just don't
// install it" is not available — a build-time alias is mandatory.
// This is design doc 5.5's identity -> cf-identity substitution; M0 shows it is
// a requirement, not an optimisation.
const ALIASES = {
  '@deepseek-ai/dsh-anonymous-user-id': `
    // Minimal cf-identity placeholder: identity comes from the U1 JWT claims.
    // Nothing is generated or persisted inside U2.
    export function getOrCreateAnonymousUserId() { return 'cf-tenant-user' }
    export function readAnonymousUserId() { return 'cf-tenant-user' }
    export function anonymousUserId() { return 'cf-tenant-user' }
    export default { getOrCreateAnonymousUserId, readAnonymousUserId, anonymousUserId }
  `,

  // dsh-host-apiproxy statically imports this, and it imports node:child_process
  // to hand a path to the desktop's file manager. There is no desktop here.
  //
  // The dead code path is already configured off -- ApiProxyService takes
  // `nativeOpen`, and U2 sets it false, so `canOpenPath()` reports false and the
  // client never offers "reveal in folder". But configuration does not remove a
  // static import, and one unreachable import is enough to fail the bundle gate.
  //
  // Throwing rather than resolving: if something ever does reach this, a clear
  // error naming the reason beats a silent no-op that looks like the file
  // manager simply did not open.
  '@deepseek-ai/dsh-native-command': `
    export function runNativeCommand() {
      throw new Error('cf: native commands are not available in a Worker (there is no desktop to open a path on)')
    }
    export default { runNativeCommand }
  `,
}
const aliasPlugin = {
  name: 'upstream-alias',
  setup(build) {
    const filter = new RegExp(`^(${Object.keys(ALIASES).map(k => k.replace(/[/@-]/g, '\\$&')).join('|')})$`)
    build.onResolve({ filter }, (args) => ({ path: args.path, namespace: 'alias' }))
    build.onLoad({ filter: /.*/, namespace: 'alias' }, (args) => ({
      contents: ALIASES[args.path], loader: 'js',
    }))
  },
}

// M0 finding #3, the hardest to predict: dsh-api-gateway runs
//     var NEVER_ABORTED_SIGNAL = new AbortController().signal
// at module scope. workerd counts constructing an AbortController as a
// disallowed global-scope operation, so import throws.
// AbortController is neither a Node builtin nor on any "dangerous API" list —
// only actually running workerd surfaces this. In production the fix is either
// this build-time rewrite or one of ADR-04's three pnpm patch slots.
const NEVER_ABORTED = '({ aborted: false, reason: undefined, onabort: null, ' +
  'addEventListener() {}, removeEventListener() {}, dispatchEvent() { return false }, throwIfAborted() {} })'
const rewrites = []
// A rewrite that was tried here and taken back out, because it was half a fix.
//
// dsh-workspace resolves and validates every workspace path against the HOST
// filesystem: one `realpath()` and four `stat(...).isDirectory()` calls. On
// workerd that filesystem holds only /bundle, /tmp and /dev, while the workspace
// lives in a container reached over a service binding, so `workspace.create`
// fails with "no such file or directory" about a path that exists perfectly
// well -- just not here.
//
// Rewriting realpath to pure normalisation made the first call pass and the
// next one fail with a differently confusing message. Making them all pass
// means blinding the validation entirely: every path becomes a valid workspace,
// including ones that exist nowhere. That is the failure mode this project has
// spent its time on -- configured-looking and silently wrong -- so the registry
// is left reporting an honest error instead, and design 6.3's per-tenant
// workspace registry is where it gets solved, doing its checks through the fs
// seam like cf-workspace-picker already does.

const lazySignal = {
  name: 'defer-module-scope-abortcontroller',
  setup(build) {
    build.onLoad({ filter: /[/\\]@deepseek-ai[/\\][^/\\]+[/\\]lib[/\\].*\.(js|mjs)$/ }, async (args) => {
      const { readFile } = await import('node:fs/promises')
      const src = await readFile(args.path, 'utf8')
      // Only the module-scope assignment form is rewritten; uses inside a
      // function body are left alone.
      let out = src.replace(
        /^(\s*(?:var|let|const)\s+\w+\s*=\s*)new AbortController\(\)\.signal/gm,
        (_, head) => head + NEVER_ABORTED
      )
      if (out !== src) rewrites.push(args.path.replace(/^.*@deepseek-ai[/\\]/, ''))
      return { contents: out, loader: 'js' }
    })
  },
}

const result = await esbuild.build({
  entryPoints: ['./units/session-do/src/index.mjs'],
  bundle: true,
  format: 'esm',
  platform: 'browser',
  conditions: ['workerd', 'worker', 'browser', 'import', 'module', 'default'],
  external: ['node:*', 'cloudflare:*'],
  plugins: [stubPlugin, requireShim, aliasPlugin, lazySignal],
  outfile: './units/session-do/build/u2.bundle.js',
  metafile: true,
  logLevel: 'silent',
  logLimit: 0,
})

const out = readFileSync('./units/session-do/build/u2.bundle.js', 'utf8')
const found = new Map()
let m
while ((m = NODE_RE.exec(out))) {
  const mod = (m[1] || m[2] || m[3]).split('/')[0]
  found.set(mod, (found.get(mod) || 0) + 1)
}

// Modules workerd exposes as non-functional stubs: they import fine and throw
// when called. This is why "bundle resolves cleanly" is not a real gate.
const STUBS = new Set(['child_process', 'worker_threads', 'vm', 'sqlite', 'cluster', 'dgram',
  'domain', 'http2', 'inspector', 'readline', 'repl', 'trace_events', 'tty', 'v8', 'wasi'])

const kb = Math.round(out.length / 1024)
console.log('module-scope AbortController rewrites:', rewrites.length ? rewrites.join(', ') : '(none)')
console.log(`entry packages: ${deps.length}`)
console.log(`bundle: ${kb} KB (unminified)`)
console.log(`\n=== residual node: builtins (${found.size}) ===`)
const rows = [...found].sort((a, b) => b[1] - a[1])
for (const [mod, n] of rows) {
  const bad = STUBS.has(mod)
  console.log(`  ${bad ? '[STUB!]' : '[ ok  ]'} node:${mod.padEnd(18)} ${n} references`)
}
const blockers = rows.filter(([m]) => STUBS.has(m))

console.log(`\n=== bare builtin specifiers (unresolvable on workerd; must be stubbed or aliased) ===`)
const bareRows = [...bareHits].sort((a, b) => b[1].size - a[1].size)
for (const [mod, importers] of bareRows) {
  const bad = STUBS.has(mod)
  console.log(`  ${bad ? '[STUB!]' : '[ ok  ]'} ${mod.padEnd(16)} from ${importers.size} modules`)
  for (const imp of [...importers].slice(0, 4)) console.log(`             <- ${imp.slice(0, 92)}`)
  if (importers.size > 4) console.log(`             <- ...and ${importers.size - 4} more`)
}
const bareBlockers = bareRows.filter(([m]) => STUBS.has(m)).map(r => r[0])

console.log(`\nbundle check: ${blockers.length === 0 && bareBlockers.length === 0
  ? 'clean - no stub-level builtin reachable (now boot it in workerd)'
  : 'needs work - node: prefixed[' + blockers.map(b => b[0]).join(', ') + '] bare[' + bareBlockers.join(', ') + ']'}`)

// Largest contributors, to catch dead weight dragged in transitively.
const inputs = Object.entries(result.metafile.outputs['units/session-do/build/u2.bundle.js'].inputs)
  .map(([f, v]) => [f, v.bytesInOutput]).sort((a, b) => b[1] - a[1]).slice(0, 12)
console.log(`\n=== largest modules in the bundle ===`)
for (const [f, b] of inputs) console.log(`  ${(b / 1024).toFixed(1).padStart(8)} KB  ${f.replace(/^node_modules\/\.pnpm\//, '').slice(0, 96)}`)

writeFileSync('./units/session-do/build/m0-report.json', JSON.stringify({
  entryPackages: deps.length, bundleKB: kb,
  builtins: Object.fromEntries(found), blockers: blockers.map(b => b[0]),
}, null, 2))
